y"><i class="bi bi-bell-fill me-1"></i>Lưu kế hoạch và nhắc hẹn</button></div></form></div><div class="col-xl-5"><div class="d-flex gap-2 flex-wrap mb-3"><span class="badge-soft badge-info">Hôm nay: {{$personalStats['today']}}</span><span class="badge-soft badge-warning">Sắp tới: {{$personalStats['upcoming']}}</span><span class="badge-soft badge-danger">Quá hạn: {{$personalStats['overdue']}}</span></div><div class="upcoming-list">@forelse($personalPlans as $plan)<div class="upcoming-item priority-{{$plan->priority}}"><div class="upcoming-time"><strong>{{$plan->scheduled_for->format('d/m')}}</strong><span>{{$plan->scheduled_for->format('H:i')}}</span></div><div class="upcoming-copy"><strong>{{$plan->title}}</strong><small>{{$plan->scheduled_for->isPast()?'Đã quá hạn':$plan->scheduled_for->diffForHumans()}}</small></div><form method="POST" action="{{route('plans.toggle',$plan)}}">@csrf @method('PATCH')<button class="btn btn-sm btn-outline-success"><i class="bi bi-check2"></i></button></form></div>@empty<div class="empty-state py-4">Chưa có kế hoạch cá nhân.</div>@endforelse</div></div></div></div></div></div></div>

