@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const month=document.querySelector('[data-month-filter]'),quarter=document.querySelector('[data-quarter-filter]');month?.addEventListener('change',()=>{if(month.value&&quarter)quarter.value=''});quarter?.addEventListener('change',()=>{if(quarter.value&&month)month.value=''});const lead=document.querySelector('[data-task-lead]'),items=[...document.querySelectorAll('input[name="assignee_ids[]"]')];if(lead){const old=lead.dataset.oldValue,refresh=()=>{const selected=lead.value||old;lead.innerHTML='<option value="">Chọn người chủ trì</option>';items.filter(i=>i.checked).forEach(i=>lead.add(new Option(i.dataset.assigneeName,i.value,false,i.value===selected)));if(![...lead.options].some(o=>o.value===selected))lead.value=''};items.forEach(i=>i.addEventListener('change',refresh));refresh()}@if($errors->any())const modal=document.getElementById(@json(old('scheduled_for')?'personalPlanModal':'assignTaskModal'));if(modal)bootstrap.Modal.getOrCreateInstance(modal).show();@endif});</script>@endpush
